function Config.HolidayWarOrderData.data_constant_fun(slot0)
	slot1 = Config.HolidayWarOrderData.data_constant[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.HolidayWarOrderData.data_constant[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

